<template>
  <div class="page-generator">
    <!-- Header -->
    <div class="header">
      <h1>📄 Static Page Generator</h1>
      <div class="header-actions">
        <button @click="clearAll" class="btn btn-outline">Clear All</button>
        <button @click="exportCode" class="btn btn-primary">Export HTML</button>
      </div>
    </div>

    <!-- Main Content: Form Builder (Left) + Code Output (Right) -->
    <div class="main-layout">
      <!-- LEFT: Form Builder -->
      <div class="builder-panel">
        <div class="panel-header">
          <h3>🏗️ Element Builder</h3>
          <button @click="addElement" class="btn btn-success btn-sm">+ Add Element</button>
        </div>

        <!-- Elements List -->
        <div class="elements-list">
          <div v-for="(element, idx) in elements" :key="element.id" class="element-card">
            <div class="element-header">
              <span class="element-index">{{ idx + 1 }}</span>
              <span class="element-tag">{{ element.tag }}</span>
              <div class="element-actions">
                <button @click="duplicateElement(idx)" class="icon-btn" title="Duplicate">📋</button>
                <button @click="removeElement(idx)" class="icon-btn delete" title="Remove">🗑️</button>
              </div>
            </div>

            <div class="element-form">
              <!-- Tag Select -->
              <div class="form-row">
                <label>Tag</label>
                <select v-model="element.tag">
                  <option value="div">div</option>
                  <option value="section">section</option>
                  <option value="article">article</option>
                  <option value="header">header</option>
                  <option value="footer">footer</option>
                  <option value="nav">nav</option>
                  <option value="main">main</option>
                  <option value="h1">h1</option>
                  <option value="h2">h2</option>
                  <option value="h3">h3</option>
                  <option value="p">p</option>
                  <option value="span">span</option>
                  <option value="button">button</option>
                  <option value="a">a</option>
                  <option value="img">img</option>
                  <option value="ul">ul</option>
                  <option value="li">li</option>
                  <option value="input">input</option>
                  <option value="form">form</option>
                </select>
              </div>

              <!-- Content (for non-void elements) -->
              <div class="form-row" v-if="!isVoidElement(element.tag)">
                <label>Content</label>
                <textarea v-model="element.content" rows="2" placeholder="Inner text or HTML..."></textarea>
              </div>

              <!-- Attributes -->
              <div class="form-section">
                <label class="section-label">Attributes</label>
                <div class="attributes-group">
                  <div class="attr-row">
                    <input type="text" v-model="element.idAttr" placeholder="id" class="attr-input">
                    <input type="text" v-model="element.classes" placeholder="Bootstrap classes (space separated)" class="attr-input">
                  </div>
                  <div class="attr-row">
                    <input type="text" v-model="element.href" placeholder="href (for a tag)" class="attr-input" v-if="element.tag === 'a'">
                    <input type="text" v-model="element.src" placeholder="src (for img)" class="attr-input" v-if="element.tag === 'img'">
                    <input type="text" v-model="element.alt" placeholder="alt (for img)" class="attr-input" v-if="element.tag === 'img'">
                    <input type="text" v-model="element.type" placeholder="type (for input/button)" class="attr-input" v-if="element.tag === 'input' || element.tag === 'button'">
                    <input type="text" v-model="element.dataBsToggle" placeholder="data-bs-toggle" class="attr-input" v-if="element.tag === 'button' || element.tag === 'a'">
                    <input type="text" v-model="element.dataBsTarget" placeholder="data-bs-target" class="attr-input" v-if="element.tag === 'button' || element.tag === 'a'">
                  </div>
                </div>
              </div>

              <!-- Styles (Inline CSS) -->
              <div class="form-section">
                <label class="section-label">Inline Styles (CSS)</label>
                <div class="styles-group">
                  <div v-for="(style, sIdx) in element.styles" :key="sIdx" class="style-row">
                    <input type="text" v-model="style.property" placeholder="property" class="style-prop">
                    <span>:</span>
                    <input type="text" v-model="style.value" placeholder="value" class="style-value">
                    <button @click="removeStyle(idx, sIdx)" class="icon-btn-small">✖</button>
                  </div>
                  <button @click="addStyle(idx)" class="btn-add-style">+ Add Style</button>
                </div>
              </div>

              <!-- Add this button in the element form -->
<div class="form-section">
  <label class="section-label">Nested Elements</label>
  <button @click="addChild(idx)" class="btn-add-style">+ Add Child Element</button>
  
  <!-- Display children -->
  <div v-if="element.children && element.children.length" class="children-list">
    <div v-for="(child, cIdx) in element.children" :key="child.id" class="child-card">
      <div class="child-header">
        <span class="child-tag">{{ child.tag }}</span>
        <div class="child-actions">
          <button @click="editChild(idx, cIdx)" class="icon-btn-small">✏️</button>
          <button @click="removeChild(idx, cIdx)" class="icon-btn-small">🗑️</button>
        </div>
      </div>
      <div class="child-preview">{{ child.content || '(has children)' }}</div>
    </div>
  </div>
</div>

            </div>
          </div>

          <div v-if="elements.length === 0" class="empty-state">
            <p>No elements yet. Click "Add Element" to start building your page.</p>
          </div>
        </div>
      </div>

      <!-- RIGHT: Code Output -->
      <div class="code-panel">
        <div class="panel-header">
          <h3>📝 Generated HTML Code</h3>
          <button @click="copyCode" class="btn btn-outline btn-sm">Copy Code</button>
        </div>
        <div class="code-container">
          <pre><code class="language-html">{{ generatedCode }}</code></pre>
        </div>
        <div class="preview-header">
          <h3>👁️ Live Preview</h3>
          <div class="preview-actions">
            <button @click="refreshPreview" class="btn btn-outline btn-sm">🔄 Refresh Preview</button>
          </div>
        </div>
        <div class="preview-container">
          <iframe ref="previewFrame" :srcdoc="previewHtml" class="preview-frame" sandbox="allow-same-origin allow-scripts allow-popups allow-forms allow-modals"></iframe>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'StaticPageGenerator',
  data() {
    return {
      elements: [],
      nextId: 1,
      previewKey: 0, // Force iframe refresh
    };
  },
  computed: {
    // Generate HTML code from elements
    generatedCode() {
      const html = this.elements.map(el => this.renderElement(el)).join('\n');
      return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Generated Page</title>
  <!-- Bootstrap CSS -->
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: system-ui, -apple-system, sans-serif; padding: 20px; background: #f5f5f5; }
    .page-container { max-width: 1200px; margin: 0 auto; background: white; padding: 20px; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
  </style>
</head>
<body>
  <div class="page-container">
${html.split('\n').map(line => '    ' + line).join('\n')}
  </div>
  <!-- Bootstrap JS Bundle -->
  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"><\/script>
</body>
</html>`;
    },
    // Preview HTML (with Bootstrap and better compatibility)
    previewHtml() {
      const html = this.elements.map(el => this.renderElement(el)).join('\n');
      return `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet">
  <style>
    body { 
      font-family: system-ui, sans-serif; 
      padding: 20px; 
      background: #f5f5f5; 
      margin: 0;
    }
    .preview-wrapper { 
      background: white; 
      padding: 20px; 
      border-radius: 12px; 
      box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    }
    /* Additional styles to ensure Bootstrap components display correctly */
    .preview-wrapper [class*="col-"] {
      float: none;
    }
    .clearfix::after {
      display: block;
      clear: both;
      content: "";
    }
  </style>
</head>
<body>
  <div class="preview-wrapper">
${html.split('\n').map(line => '    ' + line).join('\n')}
  </div>
  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"><\/script>
  <script>
    // Initialize all Bootstrap components
    document.addEventListener('DOMContentLoaded', function() {
      // Initialize tooltips if any
      var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'))
      var tooltipList = tooltipTriggerList.map(function (tooltipTriggerEl) {
        return new bootstrap.Tooltip(tooltipTriggerEl)
      })
      
      // Initialize popovers if any
      var popoverTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="popover"]'))
      var popoverList = popoverTriggerList.map(function (popoverTriggerEl) {
        return new bootstrap.Popover(popoverTriggerEl)
      })
    });
  <\/script>
</body>
</html>`;
    },
  },
  watch: {
    elements: {
      deep: true,
      handler() {
        // Force iframe refresh when elements change
        this.refreshPreview();
      }
    }
  },
  methods: {
    // Check if tag is void (self-closing)
    isVoidElement(tag) {
      const voidTags = ['img', 'input', 'br', 'hr', 'meta', 'link'];
      return voidTags.includes(tag);
    },

      addChild(parentIndex) {
  const newChild = {
    id: this.nextId++,
    tag: 'div',
    content: 'Child element',
    idAttr: '',
    classes: '',
    styles: [],
    children: []
  };
  if (!this.elements[parentIndex].children) {
    this.elements[parentIndex].children = [];
  }
  this.elements[parentIndex].children.push(newChild);
},

removeChild(parentIndex, childIndex) {
  this.elements[parentIndex].children.splice(childIndex, 1);
},

editChild(parentIndex, childIndex) {
  // You can open a modal or inline editor for the child
  // For simplicity, we'll prompt for edits
  const child = this.elements[parentIndex].children[childIndex];
  const newTag = prompt('Enter tag name:', child.tag);
  if (newTag) child.tag = newTag;
  const newContent = prompt('Enter content:', child.content);
  if (newContent !== null) child.content = newContent;
  const newClasses = prompt('Enter classes:', child.classes);
  if (newClasses !== null) child.classes = newClasses;
},

    // Render a single element to HTML string
// Replace renderElement with this recursive version
renderElement(el) {
  // Build attributes string
  let attrs = '';
  if (el.idAttr) attrs += ` id="${this.escapeHtml(el.idAttr)}"`;
  if (el.classes) attrs += ` class="${this.escapeHtml(el.classes)}"`;
  if (el.href && el.tag === 'a') attrs += ` href="${this.escapeHtml(el.href)}"`;
  if (el.src && el.tag === 'img') attrs += ` src="${this.escapeHtml(el.src)}"`;
  if (el.alt && el.tag === 'img') attrs += ` alt="${this.escapeHtml(el.alt)}"`;
  if (el.type && (el.tag === 'input' || el.tag === 'button')) attrs += ` type="${this.escapeHtml(el.type)}"`;
  if (el.dataBsToggle) attrs += ` data-bs-toggle="${this.escapeHtml(el.dataBsToggle)}"`;
  if (el.dataBsTarget) attrs += ` data-bs-target="${this.escapeHtml(el.dataBsTarget)}"`;
  
  // Build inline style string
  const validStyles = el.styles.filter(s => s.property.trim() && s.value.trim());
  if (validStyles.length > 0) {
    const styleStr = validStyles.map(s => `${s.property.trim()}: ${s.value.trim()}`).join('; ');
    attrs += ` style="${this.escapeHtml(styleStr)}"`;
  }
  
  // Handle void elements
  if (this.isVoidElement(el.tag)) {
    return `<${el.tag}${attrs}>`;
  }
  
  // Handle children recursively
  let childrenHtml = '';
  if (el.children && el.children.length > 0) {
    childrenHtml = el.children.map(child => this.renderElement(child)).join('\n');
  }
  
  // Use children if present, otherwise use content
  const innerContent = childrenHtml || (el.content || '');
  
  return `<${el.tag}${attrs}>${innerContent}</${el.tag}>`;
},
    escapeHtml(str) {
      if (!str) return '';
      return str
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    },
// In data(), add children array to each element
addElement() {
  this.elements.push({
    id: this.nextId++,
    tag: 'div',
    content: '',
    idAttr: '',
    classes: '',
    href: '',
    src: '',
    alt: '',
    type: '',
    dataBsToggle: '',
    dataBsTarget: '',
    styles: [],
    children: [] // Add this for nested elements
  });
},
    duplicateElement(index) {
      const original = this.elements[index];
      const duplicate = JSON.parse(JSON.stringify(original));
      duplicate.id = this.nextId++;
      duplicate.content = original.content + ' (copy)';
      this.elements.splice(index + 1, 0, duplicate);
    },
    removeElement(index) {
      this.elements.splice(index, 1);
    },
    addStyle(elementIndex) {
      this.elements[elementIndex].styles.push({ property: '', value: '' });
    },
    removeStyle(elementIndex, styleIndex) {
      this.elements[elementIndex].styles.splice(styleIndex, 1);
    },
    clearAll() {
      if (confirm('Clear all elements?')) {
        this.elements = [];
        this.nextId = 1;
      }
    },
    copyCode() {
      navigator.clipboard.writeText(this.generatedCode);
      alert('HTML code copied to clipboard!');
    },
    exportCode() {
      const blob = new Blob([this.generatedCode], { type: 'text/html' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'generated-page.html';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    },
    refreshPreview() {
      // Force iframe to reload by updating the srcdoc
      if (this.$refs.previewFrame) {
        const frame = this.$refs.previewFrame;
        const srcdoc = this.previewHtml;
        frame.srcdoc = srcdoc;
      }
    }
  },



  mounted() {
    // Add a default element with Bootstrap styling
    this.addElement();
  }
};
</script>

